// Hand-written `@nestjs/bullmq` stub for the flowatlas fixture suite. It declares
// only what `fixtures/nest-bullmq/src` touches, in the real library's shape.
//
// This is the bullmq-era API: a `@Processor('<queue>')` class extends
// `WorkerHost` and implements a single `process(job)`. The bull-era
// `@Processor` + `@Process` pair lives in `@nestjs/bull`, which is stubbed
// separately — both packages map to the one `bullmq` adapter (§7).

import type { Job } from 'bullmq';

/**
 * Both overloads the real library declares, because the fixture exercises both:
 * a bare queue name, and the options object whose `name` is the queue. A stub
 * that declared only the first would let the fixture prove something the real
 * package does not do (R63).
 */
export interface WorkerHostProcessorOptions {
  name?: string;
  concurrency?: number;
}
export declare function Processor(queueName?: string, options?: unknown): ClassDecorator;
export declare function Processor(options: WorkerHostProcessorOptions): ClassDecorator;
export declare function InjectQueue(name?: string): ParameterDecorator;
export declare function InjectFlowProducer(name?: string): ParameterDecorator;
export declare function OnWorkerEvent(event: string): MethodDecorator;

export declare abstract class WorkerHost {
  abstract process(job: Job, token?: string): Promise<unknown>;
}

export declare class BullModule {
  static forRoot(options: { connection?: { host?: string; port?: number } }): any;
  static registerQueue(...options: Array<{ name: string }>): any;
}
